  ["quest:aht_urhgan:102"] = {
    objective_name = "Royal Painter Escort",
    page = {
      title = "Royal Painter Escort",
      page_id = 39116,
      revision_id = 1520818,
      revision_timestamp = "2015-05-30T05:30:19Z",
      content_sha256 = "334e1a7c2bba15e468b40f4012b597caddf1df8d095fda5c3351df45240dd591",
      source_url = "https://ffxiclopedia.fandom.com/wiki/Royal_Painter_Escort",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Trade an Imperial Silver Piece to Halshaob (H-10) in the southeast corner of the Nashmau Port to begin the quest.",
        action = "trade",
        entities = { "Imperial Silver Piece", "Halshaob" },
        zones = { "Nashmau" },
        map_numbers = {  },
        grid_coordinates = { "H-10" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "**",
        depth = 2,
        instruction = "Shares a once per day Earth timer with Scouting the Ashu Talif.",
        action = "note",
        entities = { "Scouting the Ashu Talif" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "Go to the Cutter in Arrapago Reef, and enter when ready. Buffs wear upon entering.",
        action = "travel",
        entities = { "Arrapago Reef" },
        zones = { "Arrapago Reef" },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "*",
        depth = 1,
        instruction = "Once inside, the NPC Faluuya will request you open a door to the ship's hold to continue. Make sure you are buffed before opening the door for her.",
        action = "use",
        entities = { "Faluuya" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "Once inside the hold, several Ashu Talif Crew spawn and attempt to attack Faluuya. These enemies will attack Faluuya regardless of whether they are provoked or not. It seems the only way to draw their attention away from her is to damage them. They are no more difficult than the Ashu Talif crew of the previous quest.",
        action = "note",
        entities = { "Ashu Talif Crew", "Faluuya" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "*",
        depth = 1,
        instruction = "If she should become damaged (a likely occurrence) she will Flee to the rear of the ship. Fight off whatever Ashu Talif crew are on her, and also the Ashu Talif Marines which spawn. The Marines are more difficult than their crew mates. Don't forget to cure Faluuya if she takes damage.",
        action = "fight",
        entities = { "Flee", "Ashu Talif Marine" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "*",
        depth = 1,
        instruction = "An NM crewman, Black Bartholomew, stands on the other side of the hold. If this crewman is defeated, all crew on board will vanish, and Faluuya will be able to sketch in peace. For this reason, you should aim to defeat it, although you should not neglect Faluuya while you are completing this task. IMPORTANT NOTE: Black Bartholomew is NOT there at start. After killing a few crew and/or marines, the NM is spawned.",
        action = "fight",
        entities = { "Black Bartholomew", "Faluuya" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "*",
        depth = 1,
        instruction = "Once Faluuya completes her work, treasure chests appear on deck. One will appear for completing the BCNM, another for killing Black Bartholomew, and a third if Faluuya took no damage. Open them, and click on the Life Raft to finish the mission.",
        action = "examine",
        entities = { "Faluuya", "Black Bartholomew" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "*",
        depth = 1,
        instruction = "Notes",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 10,
        marker = "*",
        depth = 1,
        instruction = "It is not necessary to kill the NM to get clear. If you just want an easy clear to move to the next quest; then all members stay with the NPC and none target the NM for kill. You can protect her, and while the NM will not die, she will finish her painting. She will take more damage this way, but it is possible to finish without killing the NPC.",
        action = "fight",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 11,
        marker = "*",
        depth = 1,
        instruction = "Possible to get both Yoichi's Sash and Cerberus Hide from the same run.",
        action = "note",
        entities = { "Yoichi's Sash", "Cerberus Hide" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 12,
        marker = "*",
        depth = 1,
        instruction = "Beaten easily with a 5-man party of Blue Mage, Scholar, Monk, Monk and Dancer. Blue Mage and Scholar followed the NPC to the back of the ship whilst the others killed the NM to stem the flow of Ashu Talif Crew and Marines. Blue Mage was easily able to control the crowds of Crew and Marines by rotating Frypan, Body Slam and Grand Slam. Scholar was curing NPC if she took damage.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
    },
    warnings = {  },
  },
  ["quest:aht_urhgan:103"] = {
    objective_name = "Targeting the Captain",
    page = {
      title = "Targeting the Captain",
      page_id = 39118,
      revision_id = 1520900,
      revision_timestamp = "2015-05-31T13:55:54Z",
      content_sha256 = "ae41cb3e1a3efa1463482e7fe6df0f1aafc0e481443b800e737d4dbd348f1541",
      source_url = "https://ffxiclopedia.fandom.com/wiki/Targeting_the_Captain",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Trade an Imperial Mythril Piece to Halshaob (H-10) in the south-east corner of the Nashmau Port.",
        action = "trade",
        entities = { "Imperial Mythril Piece", "Halshaob" },
        zones = { "Nashmau" },
        map_numbers = {  },
        grid_coordinates = { "H-10" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "**",
        depth = 2,
        instruction = "Shares a once per day Earth timer with Royal Painter Escort.",
        action = "note",
        entities = { "Royal Painter Escort" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "Go to the Black Coffin assault entrance, and enter when ready. Buffs wear upon entering.",
        action = "travel",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "*",
        depth = 1,
        instruction = "Buff up and walk to the rear of the ship's hold.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "There are 2 Windjammer Imps in the room where the NM spawned from the previous quest, kill those and proceed up the stairs.(Note: The Windjammer imps must be agroed from behind in order to keep Bubbly's route in a linear path. If you use a sneak attack on the imps without them seeing you he will walk back and forth instead of around the cabin when you attack the Captain.",
        action = "fight",
        entities = { "Windjammer Imp" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "**",
        depth = 2,
        instruction = "Ranged attacks as well as any ranged blue magic spell can be used to induce a \"sneak attack\" on the Imps.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "*",
        depth = 1,
        instruction = "Behind the door is Cutthroat Kabsalah (Corsair) and his pet Opo-opo, Bubbly.",
        action = "note",
        entities = { "Cutthroat Kabsalah", "Corsair", "Bubbly" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "**",
        depth = 2,
        instruction = "An ideal strategy is to kite Cutthroat Kabsalah while you focus your attention on taking down Bubbly.",
        action = "note",
        entities = { "Cutthroat Kabsalah", "Bubbly" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "**",
        depth = 2,
        instruction = "Bubbly uses all the regular Opo-opo TP moves (beware of Spinning Claw).",
        action = "note",
        entities = { "Spinning Claw" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 10,
        marker = "*",
        depth = 1,
        instruction = "It is possible to pull Bubbly without getting aggro from Cutthroat Kabsalah. However, even if you do get Cutthroat Kabsalah's attention, he moves very slowly and it is reported that you can evade him long enough to lose hate.",
        action = "note",
        entities = { "Bubbly", "Cutthroat Kabsalah" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 11,
        marker = "*",
        depth = 1,
        instruction = "If you wish to trigger the %3F%3F%3F Gloves chest, you must successfully initiate a surprise attack on the captain. In order to do this, you must land an attack on him when he is facing away from the doorway, without garnering Bubbly's attention. You must not miss the attack nor hit for 0. Upon attack, he will say something to the effect of being surprised [Ugh, What??], and... Required details: %3F%3F%3F Gloves.",
        action = "note",
        entities = { "%3F%3F%3F Gloves" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 12,
        marker = "*",
        depth = 1,
        instruction = "The??? Gloves are not a 100% drop from the box even if you get a surprise attack on the Captain, the chances are very high but not 100%. Have occasionally gotten two??? Boxes even though a successful surprise attack was done.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 13,
        marker = "*",
        depth = 1,
        instruction = "Cutthroat Kabsalah double attacks extremely frequently (100%?) and can use a ranged attack, as well as all the standard Fomor TP moves. He will also use the Corsair 2hr job ability Wild Card, bringing his TP to 300% and immediately using one of his TP moves.",
        action = "use",
        entities = { "Cutthroat Kabsalah", "Corsair", "Wild Card (Ability)" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 14,
        marker = "*",
        depth = 1,
        instruction = "Three chests can appear. The first chest appears for successfully killing the captain (killing the opo-opo is not needed). The second chest appears for successfully landing a surprise attack and contains either %3F%3F%3F Gloves or %3F%3F%3F Box. The third chest appears for killing the opo-opo and always contains a %3F%3F%3F Box.",
        action = "note",
        entities = { "%3F%3F%3F Gloves", "%3F%3F%3F Box" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 15,
        marker = "*",
        depth = 1,
        instruction = "Section: Notes.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 16,
        marker = "*",
        depth = 1,
        instruction = "A RDM with excellent gear is able to land gravity and slow approx. 50% of the time, paralyze and ice nukes do resist.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 17,
        marker = "*",
        depth = 1,
        instruction = "The captain takes more damage from magic when inside the cabin (~800 for a tier III instead of ~ 400 outside).",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 18,
        marker = "*",
        depth = 1,
        instruction = "A BST strategy involves kiting him with a pet on the top deck; up and down the stairs while the rest of the party kills Bubbly in the back room. However, the Captain can shoot straight through doors and buildings so kiting can be rather tricky.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 19,
        marker = "*",
        depth = 1,
        instruction = "Bubbly heals himself for around 1500 hp whenever he does Magic Fruit.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 20,
        marker = "*",
        depth = 1,
        instruction = "The Captain is resistant to slow, paralyze, elegy, requiem... with very high defense and double attacks so a Paladin tank is recommended. Damage output is typically 1/3 to 1/2 of normal. He was more susceptible to skillchain damage. A BLU can pull hate with self skillchains.",
